import { AxiosError } from 'axios';
import { ILog, Verbosity } from '../../../types';
import { BaseLogstashProvider } from '../base';
import { BaseLogVerbosity } from '../types';

export class LegacyLogstashProvider extends BaseLogstashProvider<Verbosity> {
    protected handleOnSendError(logsToSend: ILog<void, Verbosity>[], _error: AxiosError<unknown, any> | Error): void {
        //legacy logger should work no bother as there are less checks so chances are the error is just down to the api being unavailable
        this.logs.push(...logsToSend);
    }

    protected get storageKey(): string {
        return 'tombola.logs';
    }

    protected get TombolaDocType(): string {
        if (this.locale === 'en-gb') {
            return 'game-uk-studio';
        } else {
            return 'game-studio';
        }
    }

    protected get endpoint(): string {
        switch (this.options.environment) {
            case 'debug':
            case 'dev':
                return 'https://devarc-api.tombola.com/logging/v4/log';
            case 'stage':
                return 'https://stage-api.tombola.com/logging/v4/log';
            default:
                return 'https://api.tombola.com/logging/v4/log';
        }
    }

    protected mapVerbosity(verbosity: BaseLogVerbosity): Verbosity {
        switch (verbosity) {
            case 'error':
                return 'ERROR';
            case 'info':
                return 'INFO';
            case 'warn':
                return 'WARN';
            default:
                return 'DEBUG1';
        }
    }
}
